package Points is

   type Point_Dimension is (Dim_1, Dim_2, Dim_3);

   type Point (D : Point_Dimension) is record
      case D is
      when Dim_1 =>
         X1         : Integer;
      when Dim_2 =>
         X2, Y2     : Integer;
      when Dim_3 =>
         X3, Y3, Z3 : Integer;
      end case;
   end record;

   procedure Display (P : Point);

end Points;

with Ada.Text_IO; use Ada.Text_IO;

package body Points is

   procedure Display (P : Point) is
   begin
      Put_Line (Point_Dimension'Image (P.D));

      case P.D is
      when Dim_1 =>
         Put_Line ("  (X => "
                   & Integer'Image (P.X1)
                   & ")");
      when Dim_2 =>
         Put_Line ("  (X => "
                   & Integer'Image (P.X2)
                   & ",");
         Put_Line ("   Y => "
                   & Integer'Image (P.Y2)
                  & ")");
      when Dim_3 =>
         Put_Line ("  (X => "
                   & Integer'Image (P.X3)
                   & ",");
         Put_Line ("   Y => "
                   & Integer'Image (P.Y3)
                   & ",");
         Put_Line ("   Z => "
                   & Integer'Image (P.Z3)
                   & ")");
      end case;
   end Display;

end Points;
